import{_ as t,c as o,b as a,a2 as s}from"./chunks/framework.BEqfOpL-.js";const r="/images/signup.webp",n="/images/select_your_podcast.webp",i="/images/onboarding_distribution.webp",l="/images/onboarding_visibility.webp",d="/images/onboarding_keywords.webp",p="/images/add_podcast_sidebar.webp",b=JSON.parse(`{"title":"Getting Started with PodSEO","description":"Welcome to PodSEO, your go-to platform for podcast competitive intelligence and SEO insights! This guide will help you quickly set up and start analyzing your podcast's performance.","frontmatter":{},"headers":[],"relativePath":"getting-started/first-steps.md","filePath":"getting-started/first-steps.md"}`),h={name:"getting-started/first-steps.md"};function c(g,e,u,y,m,f){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="getting-started-with-podseo" tabindex="-1">Getting Started with PodSEO <a class="header-anchor" href="#getting-started-with-podseo" aria-label="Permalink to &quot;Getting Started with PodSEO&quot;">​</a></h1><p>Welcome to PodSEO, your go-to platform for podcast competitive intelligence and SEO insights! This guide will help you quickly set up and start analyzing your podcast&#39;s performance.</p><hr><h2 id="_1-create-an-account" tabindex="-1">1. <strong>Create an Account</strong> <a class="header-anchor" href="#_1-create-an-account" aria-label="Permalink to &quot;1. **Create an Account**&quot;">​</a></h2><p>To access PodSEO features:</p><ul><li><p>Visit our <a href="https://podseo.com/accounts/signup/" target="_blank" rel="noreferrer">signup page</a>.</p></li><li><p>Enter your email address and accept the terms, or choose <strong>Sign up with Google</strong>.</p></li></ul><p><a href="/images/signup.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Signup Screenshot" width="250px" style="display:block;margin:0 auto;"></a></p><p>Already have an account? <a href="https://podseo.com/accounts/login/" target="_blank" rel="noreferrer">Log in</a> with a sign-in code sent to your email, your password, or Google.</p><hr><h2 id="_2-add-your-podcast" tabindex="-1">2. <strong>Add Your Podcast</strong> <a class="header-anchor" href="#_2-add-your-podcast" aria-label="Permalink to &quot;2. **Add Your Podcast**&quot;">​</a></h2><p>After logging in, you&#39;ll see <strong>Find your podcast</strong>. Search for your show and select the matching result.</p><p><a href="/images/select_your_podcast.webp" title="Open screenshot at full size"><img src="'+n+'" alt="Select Your Podcast" width="500px" style="display:block;margin:0 auto;"></a></p><p>Search using your podcast&#39;s name, its Apple Podcasts or Spotify link, or its RSS feed URL, then select it from the results. PodSEO finds shows through their Apple Podcasts listing, so make sure your show is listed there. Not launched yet? See <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a> (ready soon).</p><h2 id="_3-complete-the-onboarding-wizard" tabindex="-1">3. <strong>Complete the Onboarding Wizard</strong> <a class="header-anchor" href="#_3-complete-the-onboarding-wizard" aria-label="Permalink to &quot;3. **Complete the Onboarding Wizard**&quot;">​</a></h2><p>Once you select your podcast, PodSEO walks you through a guided setup through <strong>Connection · Goals · Positioning · Keywords · Finish</strong>:</p><p><strong>Connection</strong> — PodSEO connects your RSS feed and checks your presence across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. You&#39;ll see which platforms found your show and can continue while checks finish in the background.</p><p><a href="/images/onboarding_distribution.webp" title="Open screenshot at full size"><img src="'+i+'" alt="Onboarding Distribution" width="500px" style="display:block;margin:0 auto;"></a></p><p><strong>Goals</strong> — Choose what you want to achieve so the weekly advice follows your priorities.</p><p><strong>Positioning</strong> — Review what your show is about, who it is for, what listeners gain, and its style. These choices help PodSEO suggest relevant keywords.</p><p><a href="/images/onboarding_visibility.webp" title="Open screenshot at full size"><img src="'+l+'" alt="Onboarding Positioning" width="500px" style="display:block;margin:0 auto;"></a></p><p><strong>Keywords</strong> — PodSEO suggests initial <strong>show keywords</strong> based on your podcast&#39;s content, plus <strong>Brand</strong> keywords prefilled with your show and host names. You can review and adjust these to start building your keyword strategy.</p><p><a href="/images/onboarding_keywords.webp" title="Open screenshot at full size"><img src="'+d+'" alt="Onboarding Keywords" width="500px" style="display:block;margin:0 auto;"></a></p><p>After choosing your keywords, review the setup recap and open <strong>Home</strong>, your home base in PodSEO.</p><p>Your plan includes a set number of podcasts (Producer includes 5 and Agency 15). On any paid plan you can also buy extra podcasts with <strong>Add extra podcasts</strong> in Settings → Account; see <a href="/features/billing-and-account.html">Billing and Account Settings</a>. Use the podcast selector at the top of the sidebar to switch between podcasts, and choose <strong>Manage shows</strong> there to add or remove podcasts in Settings → Shows.</p><p>Keyword rankings are collected as a listener in the United States would see them. If your audience is mainly elsewhere, paid plans let you add search countries per podcast under <strong>Settings → Shows</strong>; see <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a> for details.</p><p><a href="/images/add_podcast_sidebar.webp" title="Open screenshot at full size"><img src="'+p+'" alt="Add Additional Podcasts" width="500px" style="display:block;margin:0 auto;"></a></p><hr><h2 id="_4-connect-your-analytics" tabindex="-1">4. <strong>Connect Your Analytics</strong> <a class="header-anchor" href="#_4-connect-your-analytics" aria-label="Permalink to &quot;4. **Connect Your Analytics**&quot;">​</a></h2><p>Bring your listening numbers into PodSEO so you can see them next to your rankings. Click <strong>Measure → Analytics</strong> in the sidebar and connect the sources you use: Spotify for Creators, Apple Podcasts Connect, YouTube, your host (Spreaker, Buzzsprout, Simplecast, Captivate, Transistor or Podigee today), OP3, or PodSEO&#39;s own hopr.fm download prefix. Every connection is free on every plan, and each tab walks you through the setup step by step. See <a href="/features/analytics-connections.html">Analytics Connections</a>. Curious why claiming your show on Apple and Spotify pays off? See <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><hr><h2 id="_5-explore-key-features" tabindex="-1">5. <strong>Explore Key Features</strong> <a class="header-anchor" href="#_5-explore-key-features" aria-label="Permalink to &quot;5. **Explore Key Features**&quot;">​</a></h2><p>Once setup is complete, PodSEO opens to the sidebar. <strong>Home</strong> sits at the top; below it, features are grouped by what you want to do: <strong>Plan</strong>, <strong>Content</strong>, <strong>Get found</strong>, <strong>Promote</strong> and <strong>Measure</strong>. Each section can be collapsed, and it opens again when you visit one of its pages. On a phone, the bottom bar has <strong>Home</strong>, <strong>Content</strong>, <strong>Get found</strong>, <strong>Promote</strong> and <strong>More</strong>, which opens the full menu. Start with Home and explore from there:</p><ul><li><p><strong><a href="/features/command-center.html">Home</a></strong> — Your dashboard home showing health signals, tasks, and insights. Start here every session.</p></li><li><p><strong><a href="/features/show-optimization.html">Show optimization</a></strong> — Review your podcast&#39;s title, author, description, and cover. Found under Content.</p></li><li><p><strong><a href="/features/planner.html">Episode Planner</a></strong> — Plan episodes and review each episode&#39;s metadata, keywords, and cover. Found under Content.</p></li><li><p><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Define your SEO strategy by saying what each keyword is for: your show, an episode, your brand, a competitor, or a theme. Found under Get found → Search Visibility.</p></li><li><p><strong><a href="/features/show-visibility.html">Search Appearances</a></strong> — Discover terms your show and episodes already rank for. Use the <strong>Show / Episodes</strong> switch.</p></li><li><p><strong><a href="/features/rankings.html">Rankings</a></strong> — Compare tracked keywords in <strong>Show</strong> or <strong>Episodes</strong> mode. Use <strong>Tracker</strong> for their history.</p></li><li><p><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — Track how often AI platforms like ChatGPT, Claude, Perplexity, and Gemini recommend your podcast. Found under Get found → AI Visibility.</p></li><li><p><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Compare your podcast with competitors. Found under Plan → Competition.</p></li><li><p><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong> — Chat with your personal SEO expert. Open <strong>LUCIA</strong> in the sidebar.</p></li></ul><hr><h2 id="_6-need-help" tabindex="-1">6. <strong>Need Help?</strong> <a class="header-anchor" href="#_6-need-help" aria-label="Permalink to &quot;6. **Need Help?**&quot;">​</a></h2><ul><li><p>Browse our Help Center for tutorials and FAQs, including our <a href="/getting-started/workflow.html">detailed keyword workflow guide</a>.</p></li><li><p>Learn more about <a href="/getting-started/visibility-score-explained.html">how the Visibility Score works</a>.</p></li><li><p>Contact support via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Settings → Contact Us</a>.</p></li><li><p>Something not working? See <a href="/more/troubleshooting.html">Troubleshooting</a>.</p></li></ul><hr><p>Start optimizing your podcast&#39;s SEO today with PodSEO. For detailed guides and advanced tips, check out our comprehensive feature documentation and academy resources.</p><p>Not live yet? Pre-launch planning is ready soon; see <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a>. Working with colleagues or clients? Set up <a href="/features/teams-and-organizations.html">Teams and Organizations</a>, then explore the <a href="/features/agency-workspace.html">Agency workspace</a> on the Agency plan.</p>',39)])])}const S=t(h,[["render",c]]);export{b as __pageData,S as default};
